"""Strict binary symbolic-test transport.

Canonical standard base64 decodes to a KTEST v3 byte stream: ASCII KTEST,
big-endian uint32 version 3, uint32 argument count followed by argument
blobs, two ignored symbolic-argv bookkeeping words, uint32 object count, then
name/data blob pairs.  Every blob is a uint32 byte length followed by exactly
that many bytes.  No trailing byte is allowed.  Object names are canonical
``x`` plus a nonnegative decimal integer with no leading zeros.
"""

import base64


class WireError(Exception):
    """A base64, binary, inventory, or leaf-range transport error."""


def decode_payload(s):
    """Strict canonical standard base64 decoding of a KTEST payload."""
    if not isinstance(s, str):
        raise WireError('payload is not a string')
    try:
        raw = s.encode('ascii')
    except UnicodeEncodeError:
        raise WireError('payload is not ASCII')
    try:
        data = base64.b64decode(raw, validate=True)
    except Exception:
        raise WireError('payload is not base64')
    if base64.b64encode(data) != raw:
        raise WireError('payload is not canonical base64')
    return data


def _canonical_name(name):
    if len(name) < 2 or name[0:1] != b'x':
        return False
    digits = name[1:]
    if digits == b'0':
        return True
    if digits[0:1] == b'0':
        return False
    for c in digits:
        if c < 48 or c > 57:
            return False
    return True


def decode_objects(data):
    """Parse a KTEST v3 byte stream into {object ID: raw data bytes}.

    Strictly validates the binary framing, argument bounds, name canonicity,
    and object uniqueness.  Raises WireError on any violation.
    """
    pos = [0]
    end = len(data)

    def take(k):
        if k < 0 or pos[0] + k > end:
            raise WireError('truncated stream')
        b = data[pos[0]:pos[0] + k]
        pos[0] += k
        return b

    def u32():
        return int.from_bytes(take(4), 'big')

    def blob(limit=None):
        n = u32()
        if limit is not None and n > limit:
            raise WireError('blob over bound')
        return take(n)

    if take(5) != b'KTEST':
        raise WireError('bad magic')
    if u32() != 3:
        raise WireError('bad version')
    argc = u32()
    if argc > 64:
        raise WireError('too many arguments')
    for _ in range(argc):
        blob(256)
    u32()  # symbolic_argv_count: ignored
    u32()  # symbolic_argv_length: ignored
    count = u32()
    objs = {}
    for _ in range(count):
        name = blob()
        value = blob()
        if not _canonical_name(name):
            raise WireError('non-canonical object name')
        key = int(name[1:])
        if key in objs:
            raise WireError('duplicate object')
        objs[key] = value
    if pos[0] != end:
        raise WireError('trailing bytes')
    return objs
